<?php
if (!defined('WHMCS')) { die('Direct access denied'); }
require_once __DIR__.'/bootstrap.php';
use CloudHost247\CartRecovery\RecoveryService;
function cloudhost247_cart_recovery_capture($vars=array()) { try { $cart=isset($_SESSION['cart'])?$_SESSION['cart']:array(); $client=(int)($_SESSION['uid']??0); $email=(string)($vars['email']??($vars['emailaddress']??'')); if(!$email && $client && class_exists('WHMCS\User\Client')) { $c=\WHMCS\User\Client::find($client); if($c){$email=$c->email;} } $currency=(string)($_SESSION['currency']??''); RecoveryService::capture($cart,$client,$email,(string)($vars['firstname']??''),(string)($vars['lastname']??''),$currency,session_id()); } catch(\Throwable $e){ RecoveryService::log('error','hook.capture_failed',array('message'=>$e->getMessage())); } }
function cloudhost247_cart_recovery_checkout($vars=array()) { try { cloudhost247_cart_recovery_capture($vars); } catch(\Throwable $e){} }
function cloudhost247_cart_recovery_convert($vars=array()) { try { $order=(int)($vars['orderid']??$vars['order_id']??0); if(!$order && !empty($vars['invoiceid'])) { $o=\WHMCS\Database\Capsule::table('tblorders')->where('invoiceid',(int)$vars['invoiceid'])->orderBy('id','desc')->first(); $order=$o?(int)$o->id:0; } if(!$order)return; $q=\WHMCS\Database\Capsule::table('mod_cloudhost247_cart_recovery_recoveries'); $rows=$q->whereIn('status',array('active','abandoned','recovered'))->where(function($x)use($vars){if(!empty($vars['userid']))$x->where('client_id',(int)$vars['userid']);})->get(); foreach($rows as $r){$revenue=null; try { $o=\WHMCS\Database\Capsule::table('tblorders')->where('id',$order)->first(); if($o && isset($o->amount) && is_numeric($o->amount)) $revenue=(float)$o->amount; } catch(\Throwable $ignored) {} $q->where('id',$r->id)->update(array('status'=>'converted','order_id'=>$order,'recovered_revenue'=>$revenue,'converted_at'=>date('Y-m-d H:i:s'),'next_reminder_at'=>null,'updated_at'=>date('Y-m-d H:i:s'))); break;} }catch(\Throwable $e){RecoveryService::log('error','hook.conversion_failed',array('message'=>$e->getMessage()));} }
if(function_exists('add_hook')){ add_hook('ClientAreaPageCart',1,'cloudhost247_cart_recovery_capture'); add_hook('ShoppingCartValidateCheckout',1,'cloudhost247_cart_recovery_checkout'); add_hook('AfterShoppingCartCheckout',1,'cloudhost247_cart_recovery_convert'); add_hook('OrderPaid',1,'cloudhost247_cart_recovery_convert'); }
